package snap

import (
	"bytes"
	"encoding/json"
	"os"
	"testing"
)

// Private capture payloads and credential material must never be checked into
// this source tree. An optional corpus is generated by the existing Python codec.
func TestCapturedNativeDatagrams(t *testing.T) {
	path := os.Getenv("NM_SNAP_CAPTURE_FIXTURE")
	if path == "" {
		t.Skip("private native capture corpus not provided")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var corpus []struct {
		Raw      []byte
		Messages []Message
	}
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatal(err)
	}
	if len(corpus) == 0 {
		t.Fatal("capture corpus empty")
	}
	for i, entry := range corpus {
		messages, err := DecodeMessages(entry.Raw)
		if err != nil {
			t.Fatalf("native datagram %d: %v", i, err)
		}
		if len(messages) != len(entry.Messages) {
			t.Fatalf("native datagram %d: message count differs", i)
		}
		for j, want := range entry.Messages {
			got := messages[j]
			if got.TypeFlags != want.TypeFlags || got.Sequence != want.Sequence || got.Command != want.Command || got.SessionID != want.SessionID || got.PacketSeq != want.PacketSeq || got.AckNumber != want.AckNumber || got.EmbeddedInMulti != want.EmbeddedInMulti || !bytes.Equal(got.Payload, want.Payload) {
				t.Fatalf("native datagram %d message %d differs from reference codec", i, j)
			}
		}
	}
	t.Logf("matched %d captured native datagrams against the existing codec", len(corpus))
}
